class Solution {
public:
    long long maxRunTime(int n, vector<int>& batteries) {
        long long sum = 0;
        for (int b : batteries) sum += b;
        long long low = 1, high = sum / n;
        while (low < high) {
            long long mid = low + (high - low + 1) / 2;
            long long total = 0;
            for (int b : batteries) {
                total += min((long long)b, mid);
            }
            if (total >= (long long)n * mid) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }
};

class Solution {
    public long maxRunTime(int n, int[] batteries) {
        long sum = 0;
        for (int b : batteries) sum += b;
        long low = 1, high = sum / n;
        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            long total = 0;
            for (int b : batteries) {
                total += Math.min((long) b, mid);
            }
            if (total >= (long) n * mid) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }
}

var maxRunTime = function(n, batteries) {
    let sum = 0n;
    for (const b of batteries) sum += BigInt(b);
    let low = 1n, high = sum / BigInt(n);
    while (low < high) {
        const mid = low + (high - low + 1n) / 2n;
        let total = 0n;
        for (const b of batteries) {
            const bBig = BigInt(b);
            total += bBig < mid ? bBig : mid;
        }
        if (total >= BigInt(n) * mid) {
            low = mid;
        } else {
            high = mid - 1n;
        }
    }
    return Number(low);
};
